var best=ls.filter(function(x){return x.r>=2&&x.r/x.n>=base+0.12}).sort(function(a,b){return b.r/b.n-a.r/a.n})[0];if(best)out.push("C'est "+dLieuPh(best.k)+" que ça répond le mieux : "+pct(best.r,best.n)+" % de réponses, contre "+Math.round(base*100)+" % en moyenne.");
ls.filter(function(x){return x.n>=4&&!x.r&&base>0}).sort(function(a,b){return b.n-a.n}).slice(0,1).forEach(function(x){out.push("Tes "+x.n+" candidatures "+dLieuPh(x.k)+" n'ont encore rien donné.")});
