ms.filter(function(x){return x.n>=4&&!x.r&&base>0&&x!==bm}).sort(function(a,b){return b.n-a.n}).slice(0,1).forEach(function(x){out.push("Aucune réponse pour l'instant sur les postes « "+x.k+" » ("+x.n+" envois) : vérifie que ton CV et ta lettre mettent bien en avant ce qu'ils demandent.")});
