function normCrit(c){var m={};(Array.isArray(c)?c:[]).forEach(function(x){if(x&&x.id)m[String(x.id).toLowerCase()]=x});return CRIT.map(function(k){var x=m[k[0]]||{na:true};var n=Math.round(+x.note);return{id:k[0],note:isFinite(n)?Math.max(0,Math.min(4,n)):0,na:!!x.na||!m[k[0]],pourquoi:String(x.pourquoi||"")}})}
